import{_ as s,o as t,c as o,ag as a}from"./chunks/framework.DPTJCqgd.js";const u=JSON.parse('{"title":"Schedule session-local reminders","description":"","frontmatter":{"editSource":"docs/user/guide/schedule.md","editSourceUrl":"https://github.com/Bestbbb/deepseek-harness-desktop/edit/c5ef947d98383a25f1481671f55bfda8e92b1a82/docs/user/guide/schedule.md"},"headers":[],"relativePath":"en/guide/schedule.md","filePath":"en/guide/schedule.md"}'),r={name:"en/guide/schedule.md"};function i(n,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="schedule-session-local-reminders" tabindex="-1">Schedule session-local reminders <a class="header-anchor" href="#schedule-session-local-reminders" aria-label="Permalink to &quot;Schedule session-local reminders&quot;">​</a></h1><p>This overlay opts one <code>dsh web</code> process into Schedule reminders without changing the shipped default Web composition:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dsh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --patch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/cli/config/examples/schedule/cordis.yml</span></span></code></pre></div><p>The current overlay supports reminders created with a positive whole-number <code>after_seconds</code>, an absolute <code>at</code> target, or a fixed-rate <code>every_seconds</code> interval of at least 300 seconds. The model manages them through <code>schedule_create</code>, <code>schedule_list</code>, and <code>schedule_delete</code>; every result identifies delivery as <code>session-local</code>.</p><p>With this overlay enabled, a successfully opened Session with active reminders shows a read-only catalog in the conversation header. It lists the complete prompt, scheduled or overdue status, one-time or exact repeating cadence, browser-local target time, and relative time. The sidebar also places a non-interactive alarm after the title of grouped, flat, and search rows when their currently available projection value is non-empty. These surfaces never create, edit, delete, or acknowledge reminders, and a cold Session&#39;s cached alarm can be briefly missing or stale.</p><p>The browser attaches its IANA zone to each prompt. Time-context tells the model to interpret otherwise-unqualified dates and times in that request&#39;s browser zone. This assumption belongs to natural-language interpretation only: <code>schedule_create.at</code> must be either a strict RFC 3339 date-time with <code>Z</code> or a numeric offset, or <code>{ date, time, time_zone }</code> with an explicit <code>UTC</code> or IANA Area/Location zone. Schedule does not retain or infer a Session default zone. Daylight-saving gaps are rejected, overlaps choose the first instant, and successful records keep only the resulting UTC target.</p><p>The original Session log owns each reminder. A live root Agent waits until it is fully idle, then queues a normal follow-up turn in that conversation. It never steers current work and adds no separate receipt or reminder card. Closing the process or leaving the Session cold stops its in-memory timer without deleting the record; reopening that same Session restores the wait and delivers an overdue reminder. Reading cold history never activates it, and a fork does not inherit its parent&#39;s reminders.</p><p>Every reminders stay aligned to their creation time. If one is overdue, only its latest due occurrence is presented and the next target remains on the original fixed-rate sequence. All distinct Every records overdue at the same idle decision are combined into one follow-up with one occurrence each; missed intervals do not create a backlog. Due one-shots run before that batch. Calendar and Cron expressions are not supported.</p><p>Create and actual delete operations acknowledge success only after Session persistence confirms their event prefix. Schedule does not provide browser, operating-system, email, SMS, or other external notification. A durable dispatch records that the follow-up was queued; it does not acknowledge model success or user receipt.</p>',9)])])}const m=s(r,[["render",i]]);export{u as __pageData,m as default};
